const orders = $json.data.orders.nodes;
const output = [];

for (const order of orders) {

  const waybillId = order.tags.find(tag =>
    /^WB-\d+$/.test(tag)
  );

  if (!waybillId) continue;

  for (const fulfillment of order.fulfillments || []) {

    for (const tracking of fulfillment.trackingInfo || []) {

      if (!tracking.number) continue;

      output.push({
        json: {
          waybill_id: waybillId,

          shopify_order_id: order.id,
          shopify_order_name: order.name,

          customer_email: order.email,

          destination_country:
            order.shippingAddress?.countryCodeV2 ?? null,

          shopify_fulfillment_id: fulfillment.id,
          shopify_fulfillment_status: fulfillment.status,

          carrier:
            tracking.company?.toLowerCase() ?? null,

          shopify_tracking_number: tracking.number
        }
      });
    }
  }
}

return output;

