parameters.jsCode:
const carrierItems = $input.all();
const shipmentItems = $('Extract Shipments').all();

// Match carrier response to Shopify shipment by tracking number.
// NEVER by array position.
const shipmentsByTracking = new Map(
  shipmentItems.map(item => [
    item.json.shopify_tracking_number,
    item.json
  ])
);

return carrierItems.map(item => {
  const carrier = item.json;

  const shipment =
    shipmentsByTracking.get(carrier.tracking_number);

  if (!shipment) {
    return {
      json: {
        carrier_tracking_number: carrier.tracking_number,
        carrier_api_status: "UNMATCHED",
        reconciliation_error: "NO_SHOPIFY_SHIPMENT_MATCH"
      }
    };
  }

  const events = carrier.events || [];
  const latestEvent = events.length
    ? events[events.length - 1]
    : null;

  const latestEventAt = latestEvent?.at || null;

  const daysSinceLastEvent = latestEventAt
    ? Math.floor(
        (Date.now() - new Date(latestEventAt).getTime()) /
        86400000
      )
    : null;

  return {
    json: {
      ...shipment,

      carrier: carrier.carrier,
      carrier_tracking_number: carrier.tracking_number,

      tracking_replaced_by: carrier.replaced_by || null,
      tracking_supersedes: carrier.supersedes || null,

      events,

      latest_event_code: latestEvent?.code || null,
      latest_event_description: latestEvent?.description || null,
      latest_event_at: latestEventAt,
      days_since_last_event: daysSinceLastEvent,

      pod_available: carrier.pod_available ?? false,
      pod_document_id: carrier.pod_document_id || null,

      delivery_anomaly: carrier.delivery_anomaly || null,

      carrier_api_status: "SUCCESS"
    }
  };
});

return $input.all().map(item => {

  const s = item.json;

  let status = "HEALTHY";
  let exception_code = null;
  let severity = "NONE";
  let action = "MONITOR";

  if (
    s.carrier_tracking_number &&
    s.shopify_tracking_number !== s.carrier_tracking_number
  ) {
    status = "EXCEPTION";
    exception_code = "TRACKING_NUMBER_MISMATCH";
    severity = "MEDIUM";
    action = "RECONCILE_TRACKING";
  }

  else if (s.delivery_anomaly) {
    status = "EXCEPTION";
    exception_code = "DELIVERY_ANOMALY";
    severity = "HIGH";
    action = "MANUAL_REVIEW";
  }

  else if (s.latest_event_code === "failed_attempt") {
    status = "WATCH";
    exception_code = "FAILED_DELIVERY_ATTEMPT";
    severity = "MEDIUM";
    action = "MONITOR";
  }

  else if (
    s.latest_event_code === "delivered" &&
    !s.pod_available
  ) {
    status = "WATCH";
    exception_code = "DELIVERED_POD_UNVERIFIED";
    severity = "MEDIUM";
    action = "CHECK_DOCUMENTS";
  }

  else if (
    s.latest_event_code !== "delivered" &&
    s.days_since_last_event !== null &&
    s.days_since_last_event > 3
  ) {
    status = "EXCEPTION";
    exception_code = "STALLED_TRACKING";
    severity = "HIGH";
    action = "CREATE_SUPPORT_TASK";
  }

  else if (s.latest_event_code === "delivered") {
    status = "HEALTHY";
    severity = "NONE";
    action = "NONE";
  }

  return {
    json: {
      ...s,
      shipment_status: status,
      exception_code,
      severity,
      recommended_action: action,
      evaluated_at: new Date().toISOString()
    }
  };
});

const legacyRefs = {
  "WB-007": "WB-1007",
  "WB-008": "WB-1008",
  "WB-009": "WB-1009",
  "WB-015": "1015",
  "WB-016": "WB-1016",
  "WB-017": "WB-1017"
};

return $input.all().map(item => {
  const s = item.json;

  const isDelivered = s.latest_event_code === "delivered";
  const isCustomsHold = s.latest_event_code === "customs_hold";

  let document_check_required = false;
  let document_type = null;
  let document_search_term = null;

  if (isDelivered && !s.pod_available) {
    document_check_required = true;
    document_type = "POD";

    // PODs are primarily linked by tracking number
    document_search_term =
      s.carrier_tracking_number ||
      s.shopify_tracking_number;
  }

  else if (isCustomsHold) {
    document_check_required = true;
    document_type = "CUSTOMS";

    // Legacy document repository may use old order references
    document_search_term =
      legacyRefs[s.waybill_id] ||
      s.waybill_id;
  }

  return {
    json: {
      ...s,
      document_check_required,
      document_type,
      document_search_term,
      canonical_reference: s.waybill_id,
      document_reference_strategy:
        document_check_required
          ? document_type === "POD"
            ? "TRACKING_NUMBER"
            : legacyRefs[s.waybill_id]
              ? "LEGACY_ORDER_REFERENCE"
              : "CANONICAL_WAYBILL_ID"
          : null
    }
  };
});

const searchResults = $input.all();

// Get the two shipments that actually required a document check
const requiredShipments = $('Prepare Document Check')
  .all()
  .map(i => i.json)
  .filter(s => s.document_check_required === true);

return requiredShipments.map(shipment => {

  const matches = searchResults
    .map(i => i.json)
    .filter(doc => {
      if (!doc || !doc.id || !doc.name) return false;

      const name = doc.name.toLowerCase();
      const term = (shipment.document_search_term || '').toLowerCase();

      return term && name.includes(term);
    });

  return {
    json: {
      ...shipment,

      document_status:
        matches.length > 0
          ? "FOUND"
          : "MISSING",

      document_matches: matches.length,

      matched_documents: matches.map(doc => ({
        id: doc.id,
        name: doc.name
      }))
    }
  };
});

return $input.all().map(item => {
  const s = item.json;

  let final_status = s.shipment_status;
  let final_exception_code = s.exception_code;
  let final_severity = s.severity;
  let final_action = s.recommended_action;

  if (s.document_status === "MISSING") {
    final_status = "EXCEPTION";
    final_exception_code =
      s.document_type === "CUSTOMS"
        ? "CUSTOMS_DOCUMENT_MISSING"
        : "POD_DOCUMENT_MISSING";

    final_severity = "HIGH";
    final_action = "CREATE_SUPPORT_TASK";
  }

  else if (s.document_status === "AMBIGUOUS") {
    final_status = "EXCEPTION";
    final_exception_code = "AMBIGUOUS_DOCUMENT_MATCH";
    final_severity = "MEDIUM";
    final_action = "MANUAL_REVIEW";
  }

  else if (
    s.document_status === "FOUND" &&
    s.document_type === "CUSTOMS" &&
    s.latest_event_code === "customs_hold"
  ) {
    final_status = "WATCH";
    final_exception_code = "CUSTOMS_HOLD_DOCUMENT_AVAILABLE";
    final_severity = "MEDIUM";
    final_action = "MONITOR_CUSTOMS";
  }

  else if (
    s.document_status === "FOUND" &&
    s.document_type === "POD"
  ) {
    final_status = "HEALTHY";
    final_exception_code = null;
    final_severity = "NONE";
    final_action = "NONE";
  }

  return {
    json: {
      ...s,
      final_status,
      final_exception_code,
      final_severity,
      final_action
    }
  };
});

return $input.all().map(item => {
  const s = item.json;

  return {
    json: {
      ...s,

      document_status: "NOT_REQUIRED",
      document_matches: 0,
      matched_documents: [],

      final_status: s.shipment_status,
      final_exception_code: s.exception_code,
      final_severity: s.severity,
      final_action: s.recommended_action
    }
  };
});

const errorItems = $input.all();
const shipments = $('Extract Shipments').all();

return errorItems.map((item) => {
  const error = item.json;

  // Try to recover tracking number from the failed HTTP request/error payload
  const errorText = JSON.stringify(error);

  const shipment = shipments.find(s => {
    const tracking = s.json.shopify_tracking_number;
    return tracking && errorText.includes(tracking);
  })?.json;

  if (!shipment) {
    return {
      json: {
        carrier_api_status: "ERROR",
        reconciliation_error: "FAILED_TO_RECOVER_SHIPMENT",
        raw_error: error
      }
    };
  }

  return {
    json: {
      ...shipment,

      carrier_tracking_number: null,
      tracking_replaced_by: null,
      tracking_supersedes: null,

      events: [],
      latest_event_code: null,
      latest_event_description: null,
      latest_event_at: null,
      days_since_last_event: null,

      pod_available: false,
      pod_document_id: null,
      delivery_anomaly: null,

      carrier_api_status: "ERROR",

      carrier_error_message:
        error.error?.message ||
        error.message ||
        "Carrier API request failed",

      shipment_status: "WATCH",
      exception_code: "CARRIER_API_UNAVAILABLE",
      severity: "MEDIUM",
      recommended_action: "RETRY_CARRIER",

      document_check_required: false,
      document_type: null,
      document_search_term: null,
      canonical_reference: shipment.waybill_id,
      document_reference_strategy: null,

      document_status: "NOT_CHECKED",
      document_matches: 0,
      matched_documents: [],

      final_status: "WATCH",
      final_exception_code: "CARRIER_API_UNAVAILABLE",
      final_severity: "MEDIUM",
      final_action: "RETRY_CARRIER",

      evaluated_at: new Date().toISOString()
    }
  };
});

const shipments = $input.all().map(i => i.json);

const orders = {};

const rank = {
  HEALTHY: 0,
  WATCH: 1,
  EXCEPTION: 2
};

for (const shipment of shipments) {

  const id = shipment.waybill_id;

  if (!orders[id]) {
    orders[id] = {
      waybill_id: id,
      shopify_order_id: shipment.shopify_order_id,
      shopify_order_name: shipment.shopify_order_name,
      customer_email: shipment.customer_email,
      destination_country: shipment.destination_country,
      shipments: []
    };
  }

  orders[id].shipments.push({
    shopify_fulfillment_id: shipment.shopify_fulfillment_id,
    tracking_number: shipment.shopify_tracking_number,

    status: shipment.final_status,
    exception_code: shipment.final_exception_code,
    severity: shipment.final_severity,
    action: shipment.final_action,

    latest_event_code: shipment.latest_event_code,
    latest_event_at: shipment.latest_event_at,

    document_status: shipment.document_status
  });
}

return Object.values(orders).map(order => {

  let order_status = "HEALTHY";

  for (const shipment of order.shipments) {
    if (
      rank[shipment.status] >
      rank[order_status]
    ) {
      order_status = shipment.status;
    }
  }

  const exceptions = order.shipments
    .filter(s => s.exception_code)
    .map(s => s.exception_code);

  const actions = [
    ...new Set(
      order.shipments
        .map(s => s.action)
        .filter(a => a && a !== "NONE")
    )
  ];

  return {
    json: {
      ...order,

      shipment_count: order.shipments.length,
      order_status,

      exception_codes: [...new Set(exceptions)],
      required_actions: actions,

      requires_attention:
        order_status !== "HEALTHY",

      rolled_up_at:
        new Date().toISOString()
    }
  };
});

const order = $json;

const statusLabels = {
  HEALTHY: "ORDER OK",
  WATCH: "MONITOR",
  EXCEPTION: "ACTION REQUIRED"
};

const shipmentSummary = order.shipments.map((s, index) => ({
  shipment: index + 1,
  tracking_number: s.tracking_number,
  status: s.status,
  latest_event: s.latest_event_code || "UNKNOWN",
  latest_event_at: s.latest_event_at || null,
  issue: s.exception_code || null,
  document_status: s.document_status,
  recommended_action: s.action || "NONE"
}));

let summary;

if (order.order_status === "HEALTHY") {
  summary = `Order ${order.waybill_id} is currently healthy. No operational intervention is required.`;
}
else if (order.order_status === "WATCH") {
  summary = `Order ${order.waybill_id} should be monitored. At least one shipment requires follow-up, but there is not yet enough evidence to classify the order as a confirmed delivery exception.`;
}
else {
  summary = `Order ${order.waybill_id} requires attention. At least one shipment has a confirmed operational exception.`;
}

return {
  json: {
    waybill_id: order.waybill_id,
    shopify_order_name: order.shopify_order_name,

    status: order.order_status,
    status_label: statusLabels[order.order_status],

    summary,

    shipment_count: order.shipment_count,
    shipments: shipmentSummary,

    issues: order.exception_codes,
    recommended_actions: order.required_actions,

    requires_attention: order.requires_attention
  }
};

