parameters.jsCode:
const orders = $input.all();

// Get form submissions from THIS execution
const formItems = $('WAYBILL — Order Intelligence').all();

if (!formItems.length) {
  throw new Error('No form submission found.');
}

const form = formItems[formItems.length - 1].json;

let requestedId =
  form['Order ID'] ??
  form.order_id ??
  '';

requestedId = String(requestedId)
  .trim()
  .toUpperCase();

if (!requestedId.startsWith('WB-')) {
  requestedId = `WB-${requestedId.replace(/^WB-?/i, '')}`;
}

const match = orders.find(
  item =>
    String(item.json.waybill_id)
      .trim()
      .toUpperCase() === requestedId
);

if (!match) {
  return [{
    json: {
      found: false,
      waybill_id: requestedId,
      status: 'NOT_FOUND',
      status_label: 'ORDER NOT FOUND',
      summary: `No WAYBILL order was found for ${requestedId}.`,
      shipments: [],
      issues: [],
      recommended_actions: []
    }
  }];
}

return [{
  json: {
    found: true,
    ...match.json
  }
}];
